38: function loadSave(){try{return Object.assign(structuredClone(defaults),JSON.parse(localStorage.getItem(SAVE_KEY)||'{}'))}catch(e){return structuredClone(defaults)}}
39: let save=loadSave();function persist(){localStorage.setItem(SAVE_KEY,JSON.stringify(save));}
40: function stepKey(pack,track,step){return `${pack}.${track}.${step}`}
41: function isDone(id){return !!save.completed[id]}
42: function completeStep(id,reward=0){if(!isDone(id)){save.completed[id]=true;save.credits+=reward;persist();return true}return false}
43: function packUnlocked(pack){return !pack.unlockRequirement?.length||pack.unlockRequirement.every(x=>isDone(x.id))}
44: function trackUnlocked(pack,index){if(!packUnlocked(pack))return false;if(index===0)return true;const prev=pack.tracks[index-1];return prev.steps?.every(s=>isDone(stepKey(pack.packId,prev.id,s.id)))??true}
45: function allCompleted(){return Object.values(save.completed).filter(Boolean).length}
46: function rewardParts(reward){if(!reward)return;['paint','kit','glow','badge'].forEach(k=>{if(reward[k]){const group=k==='paint'?'paints':k==='kit'?'kits':k==='glow'?'glows':null;if(group&&!save.unlocks[group].includes(reward[k]))save.unlocks[group].push(reward[k]);if(k==='badge')save.stats.badge=true}})}
