51:  const b=document.createElement('button');b.className='btn'+(unlocked?' primary':'');b.disabled=!unlocked||pack.packId!=='sector01';const raceDone=track.steps?.[0]&&isDone(stepKey(pack.packId,track.id,track.steps[0].id)),bossDone=track.steps?.[1]&&isDone(stepKey(pack.packId,track.id,track.steps[1].id));b.textContent=pack.packId!=='sector01'?'COMING SOON':unlocked?(raceDone&&!bossDone?'⚔ BOSS SHOWDOWN':bossDone?'REPLAY TRACK':'RACE NOW'):'LOCKED';b.onclick=()=>startRace(pack,track,!!(raceDone&&!bossDone));tc.appendChild(b);grid.appendChild(tc)});card.appendChild(grid);host.appendChild(card)});}
