cat > /tmp/opencode/neon-rush-captures/verify.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:false,args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1440,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8765/',{waitUntil:'networkidle',timeout:60000});
 await page.screenshot({path:'/tmp/opencode/neon-rush-captures/final-desktop.jpg',type:'jpeg',quality:90});
 await page.locator('#playBtn').click();
 if(!(await page.locator('#career').evaluate(el=>el.classList.contains('active')))) throw Error('Career did not open');
 await page.locator('#garageBtn').click();
 await page.locator('#playBtn').click();
 await page.locator('#garageBtn').click();
 await page.screenshot({path:'/tmp/opencode/neon-rush-captures/final-garage.jpg',type:'jpeg',quality:90});
 const garage=await page.evaluate(()=>({glows:[...document.querySelector('#glowSelect').options].map(x=>x.textContent),unlocks:document.querySelector('#garageUnlocks').textContent}));
 if(!garage.glows.includes('Cyan')) throw Error('Default glow rewards unavailable');
 await page.locator('#glowSelect').selectOption({label:'Amber'});
 if(await page.locator('#glowColor').inputValue()!=='#ffb13b') throw Error('Glow selection did not apply');
 await page.locator('#glowColor').fill('#39edff');
 await page.locator('#saveGarage').click();
 await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('neonRushCareer_v1'));s.credits=4000000;localStorage.setItem('neonRushCareer_v1',JSON.stringify(s))});
 await page.reload({waitUntil:'networkidle'});
 await page.locator('#garageBtn').click();
 await page.locator('#garageDlcBuy').click();
 const dlc=await page.evaluate(()=>JSON.parse(localStorage.getItem('neonRushCareer_v1')));
 if(!dlc.completed['shop.dlc04']||dlc.credits!==0) throw Error('DLC purchase failed');
 await page.locator('[data-close]').click();await page.locator('#playBtn').click();
 await page.locator('.track-card button').first().click();
 await page.waitForTimeout(500);
 const reset=await page.evaluate(()=>{world.player.userData.progress=1.75;world.player.userData.angle=.4;const before=world.player.userData.progress;resetCar();return {before,after:world.player.userData.progress,resets:world.player.userData.wallResets}});
 if(reset.before!==reset.after||reset.resets!==1) throw Error('Reset rewound progress: '+JSON.stringify(reset));
 const objectives=await page.evaluate(()=>{
  const d=world.player.userData;world.bots.forEach(b=>b.userData.progress=-1);world.player.userData.progress=trackLaps();
  activeStep={rule:'firstclean',drift:100};d.wallResets=0;d.drift=0;raceBoss=false;raceFinished=false;world.paused=false;finishRace();const firstclean=document.querySelector('#resultKicker').textContent;
  return {firstclean};
 });
 if(objectives.firstclean!=='RACE COMPLETE') throw Error('firstclean accepted insufficient drift');
 if(errors.length) throw Error('Browser errors: '+errors.join(' | '));
 await page.setViewportSize({width:390,height:844});await page.reload({waitUntil:'networkidle'});await page.screenshot({path:'/tmp/opencode/neon-rush-captures/final-mobile.jpg',type:'jpeg',quality:90});
 console.log(JSON.stringify({ok:true,garage,reset,objectives,errors,screenshots:['final-desktop.jpg','final-garage.jpg','final-mobile.jpg']},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
